package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Path;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Closed original dndscv selections; biological references and independent events are caller assertions. */
final class DndscvWorkflowRequest {
    private DndscvWorkflowRequest() { }
    static final String PROFILE="source-43c5e2f1beaaf3ac26df9c046b281ceb0edbfff7";
    record Request(Path mutations,String duplicates,Map<String,Object> reference,Map<String,Object> genes,
                   Map<String,Object> covariates,Map<String,Object> known,Map<String,Object> duplex,Path geneSets,
                   List<Map<String,Object>> analyses,Path source,Path out,Path rscript,Path rHome,List<Path> libraries,
                   long inputBytes,int events,int maximumGenes,long referenceBases,long matrixEntries,int chunkRows,
                   int outputFiles,int jsonBytes,int jsonNodes,long outputBytes,long auditOperations,int timeout){
        Map<String,Object> parameters(){var m=values("profile",PROFILE,"duplicate_policy",duplicates,"reference",reference,"genes",genes,"covariates",covariates,"known_cancer_genes",known,"duplex",duplex,"analyses",analyses,"gene_sets_provided",geneSets!=null,"maximum_genes",maximumGenes,"maximum_reference_bases",referenceBases,"maximum_matrix_entries",matrixEntries,"transport_chunk_rows",chunkRows);return m;}
        Map<String,Path> inputs(){var m=new LinkedHashMap<String,Path>();m.put("mutations.tsv",mutations);for(var entry:List.of(Map.entry("reference.rda",reference),Map.entry("genes.tsv",genes),Map.entry("covariates.tsv",covariates),Map.entry("known-cancer-genes.tsv",known),Map.entry("duplex-input",duplex))){Object p=entry.getValue().get("file");if(p!=null)m.put(entry.getKey(),Path.of((String)p));}if(geneSets!=null)m.put("gene-sets.tsv",geneSets);return m;}
        Map<String,Object> effective(){var m=parameters();m.putAll(values("mutations",mutations.toString(),"independent_events","caller-asserted","genetic_code",1,"source",source.toString(),"out",out.toString(),"rscript",rscript.toString(),"r_home",rHome.toString(),"r_libraries",libraries.stream().map(Path::toString).toList(),"maximum_input_bytes",inputBytes,"maximum_events",events,"maximum_output_files",outputFiles,"maximum_json_bytes",jsonBytes,"maximum_json_nodes",jsonNodes,"maximum_output_bytes",outputBytes,"maximum_audit_operations",auditOperations,"timeout_seconds",timeout));if(geneSets!=null)m.put("gene_sets",geneSets.toString());return m;}
    }
    static Request parse(Map<String,Object> m,Path parent)throws IOException{
        fields(m,"schema_version","mode","profile","independent_events","genetic_code","mutations","duplicate_policy","reference","genes","covariates","known_cancer_genes","duplex","gene_sets","analyses","source","out","rscript","r_home","r_libraries","maximum_input_bytes","maximum_events","maximum_genes","maximum_reference_bases","maximum_matrix_entries","transport_chunk_rows","maximum_output_files","maximum_json_bytes","maximum_json_nodes","maximum_output_bytes","maximum_audit_operations","timeout_seconds");integer(m.get("schema_version"),1,1);require(text(m.get("mode")).equals("SELECTION"),"Declare SELECTION mode");require(text(m.get("profile")).equals(PROFILE),"Select the exact resolved source profile; version labels and paper0.1.0 are not interchangeable");require(text(m.get("independent_events")).equals("caller-asserted"),"Explicit independent-event assertion required; read/spot counts are not independent mutations");integer(m.get("genetic_code"),1,1);String duplicates=choice(m.get("duplicate_policy"),"error","source-collapse-with-ledger");
        var reference=object(m.get("reference"));String referenceKind=choice(reference.get("kind"),"builtin","supplied-refcds");if(referenceKind.equals("builtin")){fields(reference,"kind","assembly","opportunities");choice(reference.get("assembly"),"hg19","hg38");require(text(reference.get("opportunities")).equals("verify-unweighted-standard-code"),"Built-in references require native unweighted opportunity checks");}else{fields(reference,"kind","file","assembly_label","opportunities");label(reference.get("assembly_label"));choice(reference.get("opportunities"),"as-supplied","verify-unweighted-standard-code");file(reference,parent);}
        var genes=object(m.get("genes"));String geneKind=choice(genes.get("kind"),"all","supplied");if(geneKind.equals("all"))fields(genes,"kind");else{fields(genes,"kind","file","cdkn2a_policy");choice(genes.get("cdkn2a_policy"),"exact","source-expand-isoforms");file(genes,parent);}
        var cov=object(m.get("covariates"));String covKind=choice(cov.get("kind"),"builtin","none","supplied");switch(covKind){case "builtin"->{fields(cov,"kind","name");choice(cov.get("name"),"hg19","hg19_chrx","hg19_hg38_epigenome_pcawg");if(referenceKind.equals("builtin")&&text(reference.get("assembly")).equals("hg38"))require(!text(cov.get("name")).equals("hg19"),"Choose the explicit hg38-compatible covariate database; no undeclared source default switch");}case "none"->fields(cov,"kind");default->{fields(cov,"kind","file");file(cov,parent);}}
        var known=object(m.get("known_cancer_genes"));switch(choice(known.get("kind"),"builtin","none","supplied")){case "builtin"->{fields(known,"kind","name");require(text(known.get("name")).equals("cgc81"),"Only exact original cgc81 database is named");}case "none"->fields(known,"kind");default->{fields(known,"kind","file");file(known,parent);}}
        var duplex=object(m.get("duplex"));String duplexKind=choice(duplex.get("kind"),"none","per-gene","per-site");if(duplexKind.equals("none"))fields(duplex,"kind");else{fields(duplex,"kind","file");file(duplex,parent);}
        var analyses=new ArrayList<Map<String,Object>>();var ids=new HashSet<String>();boolean needsSets=false;for(Object raw:list(m.get("analyses"))){require(analyses.size()<16,"At most16 complete analyses");var a=object(raw);fields(a,"id","seed","substitution_model","max_muts_per_gene_per_sample","max_coding_muts_per_sample","use_indel_sites","minimum_indels","maximum_covariates","constrain_truncation","output","minimum_genes_for_covariates","one_sided","gene_set_comparison");String id=text(a.get("id"));require(id.matches("[A-Za-z][A-Za-z0-9_-]{0,63}")&&ids.add(id.toLowerCase(Locale.ROOT)),"Require unique portable case-insensitive analysis IDs");integer(a.get("seed"),0,2147483647);choice(a.get("substitution_model"),"192r_3w","12r_3w","2r_3w");limit(a.get("max_muts_per_gene_per_sample"));limit(a.get("max_coding_muts_per_sample"));if(!duplexKind.equals("none"))require("Inf".equals(a.get("max_muts_per_gene_per_sample"))&&"Inf".equals(a.get("max_coding_muts_per_sample")),"Duplex analyses require both explicit Inf event limits; no hidden source overwrite");bool(a.get("use_indel_sites"));integer(a.get("minimum_indels"),1,20000000);integer(a.get("maximum_covariates"),1,1000);boolean constrained=bool(a.get("constrain_truncation"));choice(a.get("output"),"global","global-local","global-local-cv");integer(a.get("minimum_genes_for_covariates"),1,1000000);boolean oneSided=bool(a.get("one_sided"));require(!oneSided||constrained,"One-sided profile requires explicit constrained truncation; no assumed source argument overwrite");boolean sets=bool(a.get("gene_set_comparison"));needsSets|=sets;analyses.add(Collections.unmodifiableMap(a));}
        require(!analyses.isEmpty(),"Require1..16 analyses");require(m.containsKey("gene_sets")==needsSets,"Provide gene_sets exactly when at least one analysis requests comparison");var libraries=new ArrayList<Path>();var seen=new HashSet<Path>();for(String s:strings(m.get("r_libraries"),64)){Path p=resolve(parent,s);require(seen.add(p),"Duplicate declared R library");libraries.add(p);}require(!libraries.isEmpty(),"Declare exact prepared R libraries");
        return new Request(path(m,"mutations",parent),duplicates,Map.copyOf(reference),Map.copyOf(genes),Map.copyOf(cov),Map.copyOf(known),Map.copyOf(duplex),needsSets?path(m,"gene_sets",parent):null,List.copyOf(analyses),path(m,"source",parent),path(m,"out",parent),path(m,"rscript",parent),path(m,"r_home",parent),List.copyOf(libraries),number(m,"maximum_input_bytes",536870912L,1,4294967296L),(int)number(m,"maximum_events",1000000,1,20000000),(int)number(m,"maximum_genes",30000,1,200000),number(m,"maximum_reference_bases",150000000,3,1000000000),number(m,"maximum_matrix_entries",60000000,768,600000000),(int)number(m,"transport_chunk_rows",5000,1,50000),(int)number(m,"maximum_output_files",100000,1,1000000),(int)number(m,"maximum_json_bytes",67108864,1,536870912),(int)number(m,"maximum_json_nodes",10000000,1,200000000),number(m,"maximum_output_bytes",2147483648L,1,137438953472L),number(m,"maximum_audit_operations",1000000000,1,100000000000L),(int)number(m,"timeout_seconds",900,1,86400));
    }
    private static void fields(Map<String,Object> m,String... fields)throws IOException{var known=Set.of(fields);for(String key:m.keySet())require(known.contains(key),"Unknown dndscv field: "+key);}
    private static void limit(Object value)throws IOException{if(value instanceof String)require(value.equals("Inf"),"Event limit must be a nonnegative integer or literal Inf");else integer(value,0,20000000);}
    private static String choice(Object value,String... choices)throws IOException{String s=text(value);require(Set.of(choices).contains(s),"Require one of "+String.join(", ",choices));return s;}
    private static void file(Map<String,Object> m,Path parent)throws IOException{m.put("file",path(m,"file",parent).toString());}
    private static Path path(Map<String,Object> m,String key,Path parent)throws IOException{return resolve(parent,label(m.get(key)));}
    private static Map<String,Object> values(Object... pairs){var m=new LinkedHashMap<String,Object>();for(int i=0;i<pairs.length;i+=2)m.put((String)pairs[i],pairs[i+1]);return m;}
}
